/* ------------------------------------------------------------- image slots --
   Owner-supplied artwork drops into web/img/ with these exact names and the
   interface upgrades itself with no code change. Until a file exists, the slot
   falls back to the matching glyph from the owner's icon sheet, so nothing is
   ever empty and nothing external is ever fetched (default-src 'self'). */

const IMAGE_DIR = (location.protocol === "file:") ? "img/" : "/img/";

function slotImage(img, slotName, fallbackIconKey) {
  if (!img) return;
  img.dataset.slot = slotName;
  img.onerror = () => {
    img.onerror = null;
    if (ICONS[fallbackIconKey]) img.src = ICONS[fallbackIconKey];
    else img.hidden = true;
  };
  const bundled = (typeof BUNDLED_IMAGES !== "undefined") && BUNDLED_IMAGES[slotName];
  img.src = bundled || (IMAGE_DIR + slotName + ".png");
}

